/**
 * ====================================================================
 * GlucoTrack - Lightweight Canvas Line Chart Engine
 * ====================================================================
 * A clean, presentable HTML5 Canvas chart renderer.
 * Formatted and documented for student project presentation.
 * Renders smooth blood sugar trends with grid lines, points, and labels.
 */
(function (window) {
    'use strict';

    /**
     * Chart Constructor
     * @param {CanvasRenderingContext2D} ctx - HTML5 2D canvas context
     * @param {Object} config - Configuration object with data and options
     */
    function Chart(ctx, config) {
        this.ctx = ctx;
        this.canvas = ctx.canvas;
        this.config = config || {};
        this.data = config.data || { labels: [], datasets: [] };
        this.options = config.options || {};

        this.init();
    }

    /**
     * Initialize and mount the chart
     */
    Chart.prototype.init = function () {
        this.render();

        // Responsive re-rendering on window resize
        this._resizeHandler = this.render.bind(this);
        window.addEventListener('resize', this._resizeHandler);
    };

    /**
     * Main Render Loop
     */
    Chart.prototype.render = function () {
        const canvas = this.canvas;
        const ctx = this.ctx;

        // Auto-fit parent container dimensions
        const parent = canvas.parentElement;
        const rect = parent ? parent.getBoundingClientRect() : canvas.getBoundingClientRect();
        canvas.width = rect.width || 600;
        canvas.height = rect.height || 260;

        const width = canvas.width;
        const height = canvas.height;

        // Clear canvas frame
        ctx.clearRect(0, 0, width, height);

        const labels = this.data.labels || [];
        const dataset = (this.data.datasets && this.data.datasets[0]) ? this.data.datasets[0] : null;
        const values = dataset ? (dataset.data || []) : [];

        // Chart layout margins
        const padding = { top: 30, right: 35, bottom: 40, left: 55 };
        const chartW = width - padding.left - padding.right;
        const chartH = height - padding.top - padding.bottom;

        // Empty state when there are no logs
        if (values.length === 0) {
            this.drawEmptyState(ctx, width, height);
            return;
        }

        // Determine axis scale
        const minVal = 60;
        const maxVal = Math.max(200, Math.ceil((Math.max.apply(null, values) + 20) / 20) * 20);

        // 1. Draw Background Grid & Y-Axis Labels
        this.drawGrid(ctx, padding, chartW, chartH, minVal, maxVal);

        // 2. Compute Data Coordinates
        const points = [];
        const stepX = values.length > 1 ? chartW / (values.length - 1) : chartW / 2;

        for (let i = 0; i < values.length; i++) {
            const x = values.length === 1 ? padding.left + chartW / 2 : padding.left + (i * stepX);
            const val = values[i];
            const ratio = (val - minVal) / (maxVal - minVal);
            const y = padding.top + chartH - (ratio * chartH);
            points.push({ x: x, y: y, val: val, label: labels[i] || '' });
        }

        // 3. Draw Gradient Fill Under the Line
        ctx.beginPath();
        ctx.moveTo(points[0].x, padding.top + chartH);
        for (let i = 0; i < points.length; i++) {
            ctx.lineTo(points[i].x, points[i].y);
        }
        ctx.lineTo(points[points.length - 1].x, padding.top + chartH);
        ctx.closePath();
        ctx.fillStyle = dataset.backgroundColor || 'rgba(37, 99, 235, 0.12)';
        ctx.fill();

        // 4. Draw Trend Line
        ctx.beginPath();
        ctx.moveTo(points[0].x, points[0].y);
        for (let i = 1; i < points.length; i++) {
            ctx.lineTo(points[i].x, points[i].y);
        }
        ctx.strokeStyle = dataset.borderColor || '#2563eb';
        ctx.lineWidth = 3;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';
        ctx.stroke();

        // 5. Draw Circular Points & Value Badges
        for (let i = 0; i < points.length; i++) {
            const pt = points[i];

            // Outer point
            ctx.beginPath();
            ctx.arc(pt.x, pt.y, 5, 0, Math.PI * 2);
            ctx.fillStyle = '#ffffff';
            ctx.fill();
            ctx.strokeStyle = dataset.borderColor || '#2563eb';
            ctx.lineWidth = 2.5;
            ctx.stroke();

            // Value text above the point
            ctx.fillStyle = '#1e293b';
            ctx.font = 'bold 11px sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText(pt.val + ' mg/dL', pt.x, pt.y - 10);

            // Time / Date label on X-axis
            ctx.fillStyle = '#64748b';
            ctx.font = '10px sans-serif';
            ctx.fillText(pt.label, pt.x, padding.top + chartH + 20);
        }
    };

    /**
     * Draws horizontal guide lines and Y-axis units
     */
    Chart.prototype.drawGrid = function (ctx, padding, chartW, chartH, minVal, maxVal) {
        const steps = 4;
        ctx.strokeStyle = '#f1f5f9';
        ctx.lineWidth = 1;
        ctx.fillStyle = '#94a3b8';
        ctx.font = '10px sans-serif';
        ctx.textAlign = 'right';

        for (let i = 0; i <= steps; i++) {
            const y = padding.top + (i * (chartH / steps));
            const val = Math.round(maxVal - (i * ((maxVal - minVal) / steps)));

            // Horizontal grid line
            ctx.beginPath();
            ctx.moveTo(padding.left, y);
            ctx.lineTo(padding.left + chartW, y);
            ctx.stroke();

            // Y-axis label
            ctx.fillText(val + ' mg/dL', padding.left - 10, y + 4);
        }
    };

    /**
     * Draws empty state message when no data is logged
     */
    Chart.prototype.drawEmptyState = function (ctx, width, height) {
        ctx.fillStyle = '#94a3b8';
        ctx.font = '13px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('No readings yet to display on chart', width / 2, height / 2);
    };

    /**
     * Cleanup listener and reset canvas
     */
    Chart.prototype.destroy = function () {
        if (this._resizeHandler) {
            window.removeEventListener('resize', this._resizeHandler);
        }
        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    };

    // Expose Chart globally
    window.Chart = Chart;

})(window);
